package lexer

import (
	"fmt"
	"unicode"
)

// Lexer - Julia 렉서
type Lexer struct {
	input  string
	pos    int  // 현재 위치
	line   int  // 현재 줄
	column int  // 현재 열
	offset int  // 바이트 오프셋
	ch     rune // 현재 문자
	file   string
}

// NewLexer - 새로운 Lexer 생성
func NewLexer(input string) *Lexer {
	l := &Lexer{
		input:  input,
		pos:    0,
		line:   1,
		column: 0,
		offset: 0,
		ch:     rune(0),
		file:   "<stdin>",
	}
	l.readChar()
	return l
}

// NewLexerWithFile - 파일명을 포함한 Lexer 생성
func NewLexerWithFile(input, filename string) *Lexer {
	l := NewLexer(input)
	l.file = filename
	return l
}

// readChar - 다음 문자 읽기
func (l *Lexer) readChar() {
	if l.pos >= len(l.input) {
		l.ch = rune(0)
	} else {
		l.ch = rune(l.input[l.pos])
	}
	l.pos++
	l.offset++
	l.column++
}

// peekChar - 다음 문자 미리보기 (읽지 않음)
func (l *Lexer) peekChar() rune {
	if l.pos >= len(l.input) {
		return rune(0)
	}
	return rune(l.input[l.pos])
}

// peekCharN - n번째 앞의 문자 보기
func (l *Lexer) peekCharN(n int) rune {
	pos := l.pos - 1 + n
	if pos >= len(l.input) || pos < 0 {
		return rune(0)
	}
	return rune(l.input[pos])
}

// skipWhitespace - 공백과 탭 건너뛰기 (줄바꿈 제외)
func (l *Lexer) skipWhitespace() {
	for l.ch == ' ' || l.ch == '\t' || l.ch == '\r' {
		l.readChar()
	}
}

// skipLineComment - 줄 주석 건너뛰기 (#...)
func (l *Lexer) skipLineComment() {
	for l.ch != '\n' && l.ch != rune(0) {
		l.readChar()
	}
}

// skipBlockComment - 블록 주석 건너뛰기 (#=...=#)
func (l *Lexer) skipBlockComment() bool {
	if l.ch != '#' {
		return false
	}
	if l.peekChar() != '=' {
		return false
	}

	l.readChar() // '#'
	l.readChar() // '='

	depth := 1
	for depth > 0 && l.ch != rune(0) {
		if l.ch == '#' && l.peekChar() == '=' {
			l.readChar() // '#'
			l.readChar() // '='

