package parser

// Phase 2: Parser - Julia 파서 구현

import (
	"fmt"
	"juliacc/internal/ast"
	"juliacc/internal/lexer"
)

// Parser - Julia 파서
type Parser struct {
	tokens    []lexer.Token
	pos       int             // 현재 토큰 위치
	current   lexer.Token     // 현재 토큰
	errors    []ParserError
	precMap   map[lexer.TokenType]int // 연산자 우선순위
}

// ParserError - 파서 에러
type ParserError struct {
	Message string
	Token   lexer.Token
}

// NewParser - 새로운 파서 생성
func NewParser(tokens []lexer.Token) *Parser {
	p := &Parser{
		tokens:  tokens,
		pos:     0,
		errors:  []ParserError{},
		precMap: buildPrecedenceMap(),
	}
	p.advance()
	return p
}

// advance - 다음 토큰으로 이동
func (p *Parser) advance() {
	if p.pos < len(p.tokens) {
		p.current = p.tokens[p.pos]
		p.pos++
	}
}

// peek - n번째 앞의 토큰 보기
func (p *Parser) peek(n int) lexer.Token {
	pos := p.pos - 1 + n
	if pos >= len(p.tokens) {
		return p.tokens[len(p.tokens)-1] // EOF
	}
	return p.tokens[pos]
}

// match - 현재 토큰이 주어진 타입과 일치하는지 확인 및 소비
func (p *Parser) match(types ...lexer.TokenType) bool {
	for _, t := range types {
		if p.current.Type == t {
			p.advance()
			return true
		}
	}
	return false
}

// expect - 특정 토큰을 기대하고 소비, 실패 시 에러
func (p *Parser) expect(tokenType lexer.TokenType) lexer.Token {
	if p.current.Type != tokenType {
		p.error(fmt.Sprintf("예상 %v, 얻은 %v", tokenType, p.current.Type))
		return p.current
	}
	token := p.current
	p.advance()
	return token
}

// error - 에러 추가
func (p *Parser) error(msg string) {
	p.errors = append(p.errors, ParserError{
		Message: msg,
		Token:   p.current,
	})
}

// Parse - 프로그램 파싱
func (p *Parser) Parse() (*ast.Program, error) {
	stmts := []ast.Stmt{}

	for p.current.Type != lexer.TokenEOF {
		// 개행 건너뛰기
		if p.match(lexer.TokenNewline) {
			continue
		}

		stmt := p.parseStatement()
		if stmt != nil {
			stmts = append(stmts, stmt)
		}

		// 개행 또는 세미콜론 건너뛰기
		for p.match(lexer.TokenNewline, lexer.TokenSemicolon) {
		}
	}

	if len(p.errors) > 0 {
		return nil, fmt.Errorf("파싱 에러: %v", p.errors)
	}

	return &ast.Program{Statements: stmts}, nil
}

// parseStatement - 문 파싱
func (p *Parser) parseStatement() ast.Stmt {
	switch p.current.Type {
	case lexer.TokenKeywordFunction:
		return p.parseFunctionDecl()
